using Noir;
using LibVLCSharp.Shared;
using System.Text.Json;

var root=Path.Combine(Directory.GetCurrentDirectory(),"NoirValidation");
Directory.CreateDirectory(root);
var caseRoot=Path.Combine(root,"unit-"+Guid.NewGuid().ToString("N"));
var store=new LibraryStore(caseRoot);
store.State.Roots=[];store.State.Progress.Clear();
var episodes=Enumerable.Range(1,4).Select(i=>new VideoItem { Path=$"test-{i}.mkv",Title="Test",Season=1,Episode=i,Duration=100 }).ToList();
var special=new VideoItem { Path="special.mkv",Title="Test",Season=0,Episode=1,Duration=10 };
var all=episodes.Append(special).ToList();
var results=new List<string>();
void Check(bool condition,string label) { if(!condition) throw new Exception("FAIL: "+label);results.Add("PASS: "+label);Console.WriteLine(results[^1]); }
MobileChecks.Run(root,Check);
OrganizerChecks.Run(root,Check);
ProfileChecks.Run(root,Check);
PremiumChecks.Run(root,Check);
var post="https://old.reddit.com/r/television/comments/abc123/episode_discussion/comment42/?context=3";
Check(RedditDiscussion.Reddit(post)=="https://www.reddit.com/r/television/comments/abc123/episode_discussion/comment42/","Reddit discussion links preserve the exact comment and remove tracking parameters");
Check(new[]{"https://www.reddit.com/search/?q=test","https://reddit.com.evil.test/r/t/comments/abc123/","https://evil.test@reddit.com/r/t/comments/abc123/","http://reddit.com/r/t/comments/abc123/","https://reddit.com:444/r/t/comments/abc123/","https://reddit.com/r/t/comments/abc123/%22script/"}.All(u=>RedditDiscussion.Reddit(u)==null),"Discussion links reject searches, spoofed domains, credentials, insecure URLs and injected paths");
await RefreshChecks.Run(root,Check);
store.Record(episodes[1],37.42,100);
Check(store.ContinueFor(all)?.Path==episodes[1].Path,"Continue selects the interrupted episode, not episode one");
var reopened=new LibraryStore(caseRoot);
Check(Math.Abs(reopened.GetProgress(episodes[1])!.Position-37.42)<.001,"Fractional resume position survives closing and reopening the store");
Check(!reopened.GetProgress(episodes[1])!.Completed,"Stopping part-way does not mark watched");
store.Mark(episodes[1],true);store.Mark(episodes[2],true);
Check(store.ContinueFor(all)?.Path==episodes[3].Path,"Continue after watched picks the next unwatched local episode");
Check(LibraryStore.Next(episodes[3],all,store.State)==null,"Last regular episode does not auto-play specials or wrap to episode one");
store.Record(episodes[3],99.9,100);
Check(!store.GetProgress(episodes[3])!.Completed,"Seeking near the end alone does not mark watched");
Check(LibraryStore.CleanTitle("Wastemen4K")=="Wastemen","Movie title removes attached resolution suffix");
var folder=Path.Combine(caseRoot,"TV","Fixture (2024)","Season 01");Directory.CreateDirectory(folder);
File.WriteAllBytes(Path.Combine(folder,"Fixture (2024) S01E02.mkv"),[]);
var extra=Path.Combine(caseRoot,"TV","Fixture (2024)","extras");Directory.CreateDirectory(extra);File.WriteAllBytes(Path.Combine(extra,"Fixture S01E09.mkv"),[]);
store.State.Roots=[new() {Path=Path.Combine(caseRoot,"TV"),Movies=false}];store.Save();
var scan=store.Scan(out _);
Check(scan.Count==1&&scan[0].Season==1&&scan[0].Episode==2&&scan[0].Title=="Fixture","Scanner identifies season and episode and excludes extras");
var fixture=scan.Single();
store.Record(fixture,71.234,1800);store.Mark(fixture,true);
store.State.Intros[fixture.Path]=new(){Start=10,End=90};store.Save();
var artwork=Path.Combine(folder,"poster.jpg");File.WriteAllBytes(artwork,[1,2,3,4]);
scan=store.Scan(out _);fixture=scan.Single();
Check(fixture.Poster.StartsWith(Path.Combine(caseRoot,"art"))&&File.Exists(fixture.Poster),"Folder artwork is copied into permanent app storage");
store.State.Roots.Clear();store.Save();store.Scan(out _);
reopened=new LibraryStore(caseRoot);reopened.Scan(out _);
var archived=reopened.Archive.Single(x=>x.Id==fixture.Id);
Check(!archived.Available&&reopened.GetProgress(archived)!.Completed&&File.Exists(archived.Poster),"Removing a root and reopening retains watched history and artwork");
// Delete only disposable fixture files, then restore an episode under a new folder and encode name.
File.Delete(fixture.Path);File.Delete(artwork);
Check(File.Exists(archived.Poster),"Deleting media-folder artwork does not remove the cached image");
var returnedFolder=Path.Combine(caseRoot,"Returned","Fixture (2024)");Directory.CreateDirectory(returnedFolder);
File.WriteAllBytes(Path.Combine(returnedFolder,"Fixture.S01E02.1080p.mkv"),[9,8,7]);
reopened.State.Roots=[new(){Path=Path.Combine(caseRoot,"Returned")}];var returned=reopened.Scan(out _).Single();
Check(returned.Id==fixture.Id&&reopened.GetProgress(returned)!.Completed,"Re-added episode at a different path recovers its watched status");
Check(reopened.GetIntro(returned) is {End:90},"Saved intro markers survive moving an episode");
reopened.Record(returned,71.234,1800);reopened.Save();
Check(Math.Abs(new LibraryStore(caseRoot).GetProgress(returned)!.Position-71.234)<.0001,"Moved episode retains the exact fractional resume time on restart");
var movieFolder=Path.Combine(caseRoot,"Movies");Directory.CreateDirectory(movieFolder);
var moviePath=Path.Combine(movieFolder,"Example.2024.mp4");File.WriteAllBytes(moviePath,Enumerable.Range(0,1000).Select(i=>(byte)i).ToArray());
reopened.State.Roots.Add(new(){Path=movieFolder,Movies=true});var beforeMove=reopened.Scan(out _).Single(x=>x.IsMovie);
reopened.Record(beforeMove,19.875,300);var renamed=Path.Combine(movieFolder,"Totally different filename.mp4");File.Move(moviePath,renamed);
var afterMove=reopened.Scan(out _).Single(x=>x.IsMovie);
Check(afterMove.Id==beforeMove.Id&&reopened.GetProgress(afterMove)!.Position==19.875,"File fingerprint reconnects a renamed movie to its history");
reopened.RememberChapters(returned,new(){Start=50,End=140},new(){Start=1680,End=1770});
Check(reopened.CompletionStart(returned,1800)==1680,"Detected ending takes precedence over approximate completion threshold");
reopened.Record(returned,1682.25,1800,true);
reopened.State.Watchlist.Add(returned.GroupKey);reopened.State.HiddenContinue.Add(returned.GroupKey);reopened.Save();
var creditsStore=new LibraryStore(caseRoot);
var originalDates=creditsStore.ViewingHistory(returned).Select(v=>v.WatchedAt).ToList();
creditsStore.BeginViewing(returned,true);creditsStore.Record(returned,70.125,1800);
Check(creditsStore.EverWatched(returned)&&creditsStore.ViewingHistory(returned).Select(v=>v.WatchedAt).SequenceEqual(originalDates),"Starting a rewatch preserves earlier watched dates");
var interruptedRewatch=new LibraryStore(caseRoot);interruptedRewatch.BeginViewing(returned,false);interruptedRewatch.Record(returned,1682.25,1800,true);interruptedRewatch.Record(returned,1682.25,1800,true);
Check(interruptedRewatch.ViewingHistory(returned).Count==originalDates.Count+1,"Resuming a rewatch after restart adds exactly one new viewing");
interruptedRewatch.State.PersonalReviews[returned.Id]=new(){Rating=5,Note="Kept after folder removal"};interruptedRewatch.Save();
Check(new LibraryStore(caseRoot).State.PersonalReviews[returned.Id].Rating==5,"Personal rating and notes survive reopening the library");
var now=DateTimeOffset.UtcNow;
interruptedRewatch.State.EpisodeSchedules[returned.GroupKey]=[new(){Season=1,Episode=2,AirsAt=now.AddDays(-2)},new(){Season=1,Episode=3,AirsAt=now.AddDays(-1)},new(){Season=1,Episode=4,AirsAt=now.AddDays(1)},new(){Season=1,Episode=5},new(){Season=0,Episode=1,AirsAt=now.AddDays(-1)}];
Check(interruptedRewatch.MissingEpisodes(returned.GroupKey,now).Select(e=>e.Episode).SequenceEqual(new[]{3}),"Missing-episode list excludes local files, future episodes, unknown dates and specials");
interruptedRewatch.Save();Check(new LibraryStore(caseRoot).State.EpisodeSchedules[returned.GroupKey].Count==5,"Episode dates remain available offline after restarting");
var knownEpisodes=interruptedRewatch.EpisodesFor(returned.GroupKey);
Check(knownEpisodes.Count==4&&knownEpisodes.Count(e=>e.Available&&File.Exists(e.Path))==1,"Full show count includes metadata-only episodes alongside the available episode");
var missingThird=knownEpisodes.Single(e=>e.Season==1&&e.Episode==3);var missingFourth=knownEpisodes.Single(e=>e.Season==1&&e.Episode==4);
interruptedRewatch.Mark(missingThird,true);interruptedRewatch.Mark(missingFourth,false);
var virtualReload=new LibraryStore(caseRoot);
Check(virtualReload.GetProgress(missingThird)?.Completed==true&&virtualReload.GetProgress(missingFourth)?.Completed==false&&!virtualReload.State.Progress.ContainsKey(""),"Unavailable episodes have independent durable watched marks without sharing an empty file path");
var sleep=new SleepPlan{EpisodesLeft=2};Check(!sleep.EpisodeEnded()&&sleep.EpisodeEnded(),"Two-episode sleep limit stops after the second natural end");
var timedSleep=new SleepPlan{Deadline=now.AddMinutes(30)};Check(!timedSleep.TimeExpired(now.AddMinutes(29))&&timedSleep.TimeExpired(now.AddMinutes(30)),"Time sleep limit only expires at its deadline");
creditsStore=new LibraryStore(caseRoot);
Check(creditsStore.GetProgress(returned) is {Completed:true,Position:1682.25},"Watched-at-credits status and actual playback position survive restart");
Check(creditsStore.GetOutro(returned) is {Start:1680} && creditsStore.State.Watchlist.Contains(returned.GroupKey) && creditsStore.State.HiddenContinue.Contains(returned.GroupKey),"Ending markers, My List and hidden Continue titles survive restart");
creditsStore.State.MarkWatchedAtCredits=false;
Check(creditsStore.CompletionStart(returned,1800)==1800,"Disabling credits completion requires the actual file end");
var backupPath=Path.Combine(caseRoot,"backup.zip");creditsStore.ExportBackup(backupPath);
using(var backup=System.IO.Compression.ZipFile.OpenRead(backupPath))
{
    using var archivedState=backup.GetEntry("library.json")!.Open();var recovered=JsonSerializer.Deserialize<PlayerState>(archivedState)!;
    Check(recovered.Catalog[returned.Id].Progress!.Completed && recovered.Watchlist.Contains(returned.GroupKey) && backup.Entries.Any(e=>e.FullName.StartsWith("art/")),"Exported backup contains watched history, My List and cached artwork");
    Check(backup.Entries.All(e=>!e.FullName.EndsWith(".mkv") && !e.FullName.Contains("review-browser")),"Library backup excludes videos and browser session data");
}
var reviewItem=new VideoItem{Title="Example",ImdbId="tt111",EpisodeImdbId="tt222",Season=2,Episode=3};
Check(ReviewLinks.ImdbUrl(reviewItem)=="https://www.imdb.com/title/tt222/reviews/" && ReviewLinks.ImdbUrl(reviewItem,true)=="https://www.imdb.com/title/tt111/reviews/","Episode and series reviews use distinct IMDb identifiers");
reviewItem.EpisodeImdbId="";
Check(ReviewLinks.ImdbUrl(reviewItem).EndsWith("/episodes/?season=2"),"An unmatched episode opens its series season list instead of an unreliable combined search");
reviewItem.IsMovie=true;
Check(ReviewLinks.LetterboxdUrl(reviewItem)=="https://letterboxd.com/imdb/tt111/","Letterboxd resolves a movie from its verified IMDb identifier");
var indexPath=Path.Combine(caseRoot,"imdb-episodes.tsv.gz");
using(var index=File.Create(indexPath))
using(var gzip=new System.IO.Compression.GZipStream(index,System.IO.Compression.CompressionMode.Compress))
using(var writer=new StreamWriter(gzip)) writer.Write("tconst\tparentTconst\tseasonNumber\tepisodeNumber\ntt900\ttt500\t2\t3\ntt901\ttt500\t2\t4\ntt902\ttt600\t1\t1\n");
var indexed=await EpisodeReviewIndex.Resolve([new(){Id="first",ImdbId="tt500",Season=2,Episode=3},new(){Id="second",ImdbId="tt500",Season=2,Episode=4},new(){Id="missing",ImdbId="tt500",Season=3,Episode=1}],caseRoot);
Check(indexed.Count==2 && indexed["first"]=="tt900" && indexed["second"]=="tt901","Cached IMDb episode index maps season and episode exactly and leaves missing episodes unresolved");
var productionCopy=Path.Combine(caseRoot,"real-copy");Directory.CreateDirectory(productionCopy);
var syncStore=new LibraryStore(Path.Combine(caseRoot,"sync"));syncStore.State.Roots=[];
syncStore.State.SyncTrakt=syncStore.State.SyncSerializd=true;
var syncEpisode=new VideoItem{Id="episode-sync",Path="sync.mkv",Title="Test",ImdbId="tt500",Season=2,Episode=3,Duration=1800};
syncStore.State.Catalog[syncEpisode.Id]=new(){Item=syncEpisode,Paths=[syncEpisode.Path]};
syncStore.Record(syncEpisode,600,1800);
Check(syncStore.State.WatchSync.Count==0,"An unfinished episode never queues a website watched mark");
syncStore.Record(syncEpisode,1740,1800,true);
var syncReload=new LibraryStore(syncStore.DataDirectory);
Check(syncReload.State.WatchSync.Count==2&&syncReload.State.WatchSync.Values.All(j=>j.SyncedAt==null),"Watched-at-credits queues both providers durably before a network request");
syncStore.Record(syncEpisode,1750,1800,true);syncStore.Mark(syncEpisode,true);
Check(syncStore.State.WatchSync.Count==2,"Repeated saves and manual marks do not duplicate sync jobs");
syncStore.State.WatchSync["Trakt:"+syncEpisode.Id].SyncedAt=DateTimeOffset.UtcNow;syncStore.Mark(syncEpisode,false);
Check(syncStore.State.WatchSync.Count==1&&syncStore.State.WatchSync.Values.Single().SyncedAt!=null,"Marking unwatched cancels unsent jobs and preserves confirmed website history");
syncStore.State.SyncTrakt=false;syncStore.Mark(syncEpisode,true);
Check(!CommunityQueue.Enabled(syncStore.State,"Trakt")&&syncStore.State.WatchSync.Count==2,"Disabled providers stop syncing while other providers can queue");
var syncMovie=new VideoItem{Id="movie-sync",IsMovie=true};CommunityQueue.Enqueue(syncStore.State,syncMovie,DateTimeOffset.UtcNow);
Check(syncStore.State.WatchSync.Values.All(j=>j.ItemId!=syncMovie.Id),"Serializd never receives movie watched marks");
syncStore.State.SyncTrakt=true;CommunityQueue.Enqueue(syncStore.State,syncMovie,DateTimeOffset.UtcNow);
Check(syncStore.State.WatchSync.Values.Count(j=>j.ItemId==syncMovie.Id)==1,"Movies queue only to Trakt");
syncStore.State.SerializdSeasons[CommunityQueue.SeasonKey(syncEpisode)]="https://www.serializd.com/show/Test-55/season/66/2";
Check(ReviewLinks.SerializdUrl(syncEpisode,syncStore.State).EndsWith("/season/66/2/episode/3")&&ReviewLinks.TraktUrl(syncEpisode)=="https://app.trakt.tv/shows/tt500/seasons/2/episodes/3","Both provider links address the exact episode");
syncStore.State.SerializdSeasons[CommunityQueue.SeasonKey(syncEpisode)]="https://example.com/show/Test-55/season/66/2";
Check(CommunityQueue.SerializdEpisode(syncStore.State,syncEpisode)=="","An invalid or foreign cached URL cannot be used for watched sync");
var appData=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),".noir");
foreach(var name in new[]{"library.json","metadata.json"}) File.Copy(Path.Combine(appData,name),Path.Combine(productionCopy,name),true);
var production=new LibraryStore(productionCopy);var archivedBeforeScan=production.Archive.Count;var library=production.Scan(out var warnings);
Check(production.Archive.Count>=archivedBeforeScan&&library.All(i=>i.Available&&File.Exists(i.Path)),"Real scan preserves archived titles while returning only existing videos");
Check(library.All(i=>!System.Text.RegularExpressions.Regex.IsMatch(i.Path,@"(?i)\b(NCOP|NCED|sample|trailer)\b")),"Extras and NC opening/ending clips stay out of the regular TV library");
Console.WriteLine($"Real library: {library.Count} videos, {library.Select(x=>x.GroupKey).Distinct().Count()} titles, {warnings.Count} warnings");
if(!args.Contains("--offline")) using(var metadataClient=new MetadataClient(caseRoot))
{
    var details=await metadataClient.Fetch(new VideoItem{Title="Dorohedoro",Year=2020,Season=1,Episode=1});
    Check(details is {SourceName:"TVmaze",Summary.Length:>20}&&File.Exists(details.Poster),"Online show lookup downloads real artwork and information without an API key");
    production.ApplyDetails(library.First(x=>x.Title=="Dorohedoro").GroupKey,details);
    var offlineStore=new LibraryStore(productionCopy);offlineStore.State.Roots.Clear();offlineStore.Scan(out _);
    var offlineItem=offlineStore.Archive.First(x=>x.Title=="Dorohedoro"&&x.Episode==1);
    Check(offlineItem.Summary==details!.Summary&&offlineItem.EpisodeTitle.Length>0&&File.Exists(offlineItem.Poster),"Downloaded details, episode names and art reload offline after root removal");
    var film=await metadataClient.Fetch(new VideoItem{Title="Wasteman",IsMovie=true,Year=2025});
    Check(film is {SourceName:"Wikipedia",Summary.Length:>20},"Public movie lookup retrieves verified film information");
    var misspelled=await metadataClient.Fetch(new VideoItem{Title="Wastemen",IsMovie=true});
    Check(misspelled is {SourceName:"Wikipedia",Summary.Length:>20}&&File.Exists(misspelled.Poster),"A unique movie match handles the existing filename typo and caches its poster");
}
Core.Initialize();using var vlc=new LibVLC("--no-video-title-show","--quiet","--vout=dummy","--aout=dummy");
using var player=new LibVLCSharp.Shared.MediaPlayer(vlc);
var real=library.First(x=>x.Title=="Dorohedoro"&&x.Season==1);
using var media=new Media(vlc,new Uri(real.Path));
Check(player.Play(media),"Bundled VLC accepts a real MKV episode");
for(int i=0;i<100&&(!player.IsSeekable||player.Time<500);i++) await Task.Delay(100);
Check(player.IsPlaying&&player.Length>60000,"Native decoder plays and reports the real duration");
player.Time=83420;
for(int i=0;i<80&&Math.Abs(player.Time-83420)>2500;i++) await Task.Delay(100);
player.SetPause(true);
Check(Math.Abs(player.Time-83420)<2500,"VLC seeks to the saved playback timestamp");
Check(player.AudioTrackDescription.Length>1&&player.SpuDescription.Length>1,"Audio and subtitle tracks are available in VLC");
var selected=player.SpuDescription.First(x=>x.Id>=0);Check(player.SetSpu(selected.Id),"Embedded subtitles can be selected");
player.Stop();
File.WriteAllText(Path.Combine(root,"checks.json"),JsonSerializer.Serialize(results,new JsonSerializerOptions { WriteIndented=true }));
Console.WriteLine("ALL CHECKS PASSED");
